head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gRsnClssCdList = "";
scwin.pageSize = 50; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
