};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        panel_mkt.hide();
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        $c.cm.setColumnProp(grd_DsclList_excel, "MKT_NM", "Show", false);
    }

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
        panel_dep_emp.show("");
    } else {
        panel_dep_emp.hide();
    }

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    // edt_FromDate.text = cGetMinusDate2(vCurDate, 7);     // 일주일전 날짜
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkComNmCond
 * @description 법인명이 있고 특정 다른 조건을 선택할때 메세지
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkComNmCond = async function() {
    let vIsurCd = txb_isur_cd.getValue();
    if (vIsurCd !== '') {
        await $c.win.alert("해당항목 선택시 법인코드(명)의 조건값이  초기화 됩니다.");
        txb_isur_cd.setValue('');
        txb_com_abbrv.setValue('');
        return;
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !공시상세--;
목록검색;
클릭-- > async function() {
    let vIsurCd = txb_isur_cd.getValue();
    const vRsnclssCnt = txb_rsn_cnt.getValue();

    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    let sRsnClssCdList = "";
    let sFormUpclssCd = "";
    let sRsnClssCd = "";
    for (let i = 1; i <= dts_Dscl_Cond.getRowCount(); i++) {
        sFormUpclssCd = dts_Dscl_Cond.getCellData(i, "EDIT_CLSS_CD");
        sRsnClssCd = dts_Dscl_Cond.getCellData(i, "FORM_CD");
        if (sRsnClssCd !== "00000") {
            sRsnClssCdList += (sRsnClssCd + ",");
        }
    }

    // 맨뒤에 ", " 제거 하기
    scwin.gRsnClssCdList = sRsnClssCdList.substr(0, sRsnClssCdList.length - 1);
    scwin.gDepCd = cmb_TeamList.getValue();
    scwin.gEmpNo = cmb_EmpList.getValue();
    fn_Search();
} < !공시상세--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.removeAll();
    let url = "";
    const url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + js_belngdepcd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&LD_MKT_TP=" + rdo_MKT_ID.getValue() + "&FORM_CD_LIST=" + scwin.gRsnClssCdList + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + 'ULDSTF15700.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url = "/DisclosureSearch.do?method=pagingAutoDsclSrch" + "&inputMessageId=AUTODSCLCOND_IN" + "&outputMessageId=AUTODSCLLIST_OUT";
    dts_DsclList.DataID = encodeURI(url + url_cond);
    dts_DsclList.reset();
    grd_Grid.show("");
};

/**
 * @method
 * @name PageNoCall
 * @description 현재 선택한 페이지번호
 * @param {*} vPageNo vPageNo
