/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.getCellData(Number(obj), "ISUR_CD");

    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name resetParam
 * @description reset Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.resetParam = function() {
    vCurrDate = $c.ut.cGetToday("yyyymmdd"); // 현재날짜

    txb_isur_cd.setValue("");
    txb_com_abbrv.setValue("");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurrDate, 7));
    edt_ToDate.setValue(vCurrDate);
    cmb_TeamList.setValue(js_dep_cd);
    cmb_EmpList.setValue("");
    scwin.setChkValue(chb_ListStatCd, false);
    scwin.setChkValue(chb_Last, false);
    rdo_MKT_ID.setValue(js_market);
    txb_rsn_cnt.setValue("");
    scwin.gRsnClssCdList = "";
};

/**
 * @method
 * @name addDsclTeamAll
 * @description 공시팀 전체 목록에 추가
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    dts_dep.setBroadcast(false);
    for (let i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.setBroadcast(true, true);
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
